function QuoteList(){const nav=useNavigate();const {quote}=useData();const [search,setSearch]=useState('');const total=quote.payment==='plan'?plans.find(plan=>plan.months===quote.plan)!.total:2850;const quotes=[{id:'OE-2026-00847',client:'Jean Kabeya',detail:'Maison individuelle · Kinshasa, RDC',date:'28 août 2026',status:quote.status,total}].filter(item=>`${item.id} ${item.client}`.toLowerCase().includes(search.toLowerCase()));return <Page title="Devis" sub="Retrouvez et suivez tous les devis de votre boutique."><div className="quoteListToolbar"><h1>Liste des devis</h1><div className="quoteListFilters"><div className="quoteListSearch"><I.Search size={17}/><input value={search} onChange={event=>setSearch(event.target.value)} placeholder="Rechercher un devis ou un client…"/></div><Button onClick={()=>nav('/dimensionnements/nouveau/client')}><I.SquarePen size={16}/> Nouveau devis</Button></div></div><Card><div className="quoteListTable"><div className="quoteListHeader"><span>Devis</span><span>Client</span><span>Statut</span><span>Montant</span><span></span></div>{quotes.map(item=><button className="quoteListRow" key={item.id} onClick={()=>nav('/devis/'+item.id)}><span><b>{item.id}</b><small>Créé le {item.date}</small></span><span className="quoteListClient"><i><I.UserRound size={18}/></i><span><b>{item.client}</b><small>{item.detail}</small></span></span><span><Badge text={item.status}/></span><strong>{item.total.toLocaleString('fr-FR')} $</strong><I.ChevronRight size={18}/></button>)}{quotes.length===0&&<p className="muted">Aucun devis ne correspond à votre recherche.</p>}</div></Card></Page>}
